import QRCode from "https://esm.sh/qrcode@1.5.3";
function val(value) {
  return String(value ?? "");
}
function qty(value) {
  return Number(value || 0).toFixed(4);
}
function initials(name) {
  return val(name || "AX").split(" ").filter(Boolean).slice(0, 2).map(part => part[0]).join("").toUpperCase();
}
function bindPrintButton() {
  const btn = document.getElementById("printBtn");
  if (!btn) return;
  btn.onclick = function () {
    window.print();
  };
}
function statusClass(status) {
  return {
    OPEN: "status-open",
    IN_PROGRESS: "status-progress",
    READY_FOR_NEXT_STEP: "status-ready",
    DONE: "status-done"
  }[status] || "";
}
function routeText(row) {
  const from = [row.sourceWarehouseCode, row.sourceWarehouseName].filter(Boolean).join(" - ");
  const to = [row.destinationWarehouseCode, row.destinationWarehouseName].filter(Boolean).join(" - ");
  if (from || to) {
    return `${from || "-"} -> ${to || "-"}`;
  }
  return row.partnerName || "-";
}
function qrPayload(h, items) {
  return ["AXON:WAREHOUSE_TASKS", `DATE=${h.reportDate || ""}`, `WAREHOUSE=${h.warehouseCode || ""}`, `COUNT=${items.length || 0}`, `PRINTED=${h.printTime || ""}`].join("|");
}
async function setQr(h, items) {
  const qr = document.getElementById("qrCode");
  const label = document.getElementById("qrLabel");
  if (!qr) return;
  qr.src = await QRCode.toDataURL(qrPayload(h, items), {
    margin: 1,
    width: 180,
    errorCorrectionLevel: "M"
  });
  label.innerText = h.reportDate || "";
}
async function render(model) {
  const h = model.header || {};
  const items = model.items || [];
  const companyDisplay = h.companyName || "";
  document.getElementById("companyName").innerText = companyDisplay;
  document.getElementById("companyLegal").innerText = "Warehouse daily task report";
  document.getElementById("companyAddress").innerText = [h.companyAddressLine1, h.companyPostalCode, h.companyCity].filter(Boolean).join(", ") || "-";
  document.getElementById("companyTax").innerText = h.companyTaxNumber || "-";
  document.getElementById("companyContact").innerText = [h.companyEmail, h.companyPhone].filter(Boolean).join(" | ") || "-";
  const logo = document.getElementById("logo");
  const fallback = document.getElementById("logoFallback");
  if (h.companyLogoPath) {
    logo.src = h.companyLogoPath;
    logo.style.display = "block";
    fallback.style.display = "none";
  } else {
    logo.style.display = "none";
    fallback.style.display = "flex";
    fallback.innerText = initials(companyDisplay);
  }
  const warehouseText = [h.warehouseCode, h.warehouseName].filter(Boolean).join(" - ") || "All Warehouses";
  document.getElementById("reportDate").innerText = h.reportDate || "";
  document.getElementById("warehouse").innerText = warehouseText;
  document.getElementById("metaReportDate").innerText = h.reportDate || "";
  document.getElementById("printTime").innerText = h.printTime || "";
  document.getElementById("printedBy").innerText = model.username || h.printedBy || "";
  const openCount = items.filter(r => r.taskStatus === "OPEN").length;
  const progressCount = items.filter(r => r.taskStatus === "IN_PROGRESS").length;
  const readyCount = items.filter(r => r.taskStatus === "READY_FOR_NEXT_STEP").length;
  const doneCount = items.filter(r => r.taskStatus === "DONE").length;
  document.getElementById("totalTasks").innerText = String(items.length);
  document.getElementById("openTasks").innerText = `${openCount + progressCount}`;
  document.getElementById("openCount").innerText = String(openCount);
  document.getElementById("progressCount").innerText = String(progressCount);
  document.getElementById("readyCount").innerText = String(readyCount);
  document.getElementById("doneCount").innerText = String(doneCount);
  document.getElementById("itemCount").innerText = `${items.length} task${items.length === 1 ? "" : "s"}`;
  document.getElementById("itemsBody").innerHTML = items.map((row, index) => `
    <tr>
      <td>${index + 1}</td>
      <td>
        <div class="task-number">${val(row.taskNumber)}</div>
        <div class="task-type">${val(row.taskType)} / ${val(row.priority)}</div>
      </td>
      <td>
        <div>${val(row.documentNumber)}</div>
        <div class="task-type">${val(row.documentType)} / ${val(row.documentStatus)}</div>
      </td>
      <td>${[row.warehouseCode, row.warehouseName].filter(Boolean).join(" - ") || "-"}</td>
      <td>${val(routeText(row))}</td>
      <td class="right">${qty(row.quantity)}</td>
      <td><span class="status-pill ${statusClass(row.taskStatus)}">${val(row.taskStatus)}</span></td>
      <td>${val(row.assignedTo || "-")}</td>
      <td>${val(row.note)}</td>
    </tr>
  `).join("");
  await setQr(h, items);
  bindPrintButton();
}
appsmith.onReady(() => {
  render(appsmith.model || {});
  bindPrintButton();
});
appsmith.onModelChange(model => {
  render(model || {});
});

